'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('buoyancy'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,amount=1,solved=false,hintDepth=0,state='ready',tested=false,history=[],seen={float:false,sink:false},saveFailed=false;
function target(v=variant,s=stage){return s===0?4+v%3:s===1?4+(v+1)%3:3+v%4;}
function mass(){return stage===0?amount:target();}
function volume(){return stage===0?target():amount;}
function outcome(m=mass(),v=volume()){return m<v?'float':m>v?'sink':'neutral';}
function label(o){return {float:t('Floats at the surface','浮在水面'),sink:t('Sinks to the bottom','沉到水底'),neutral:t('Stays submerged: neither rises nor sinks','停留水中：不上浮也不下沉')}[o];}
function goal(){const g=target();return stage===0?t(`Keep the ${g} L capsule. Change its total mass until it floats at the surface.`,`保留 ${g} 公升的貨艙，改變總質量，讓它浮在水面。`):stage===1?t(`Keep the same ${g} kg mass. Test TWO volumes: one that sinks and one that floats.`,`保持相同的 ${g} 公斤質量。測試兩個體積：一個下沉，一個浮在水面。`):t(`Carry ${g} kg. Find the SMALLEST whole-litre capsule that floats at the surface.`,`運載 ${g} 公斤。找出能浮在水面的最小整數公升貨艙。`);}
function resetTrial(){amount=stage===0?target()+1:stage===1?target()-1:target();solved=false;hintDepth=0;state='ready';tested=false;history=[];seen={float:false,sink:false};saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('buoyancy')){variant=v;stage=0;resetTrial();}
function adjust(n){if(solved||!Number.isInteger(n)||n<1||n>10)return;amount=n;tested=false;state='changed';render();}
function check(){if(solved)return;tested=true;const o=outcome();if(o==='float'||o==='sink')seen[o]=true;history.unshift({m:mass(),v:volume(),o});history=history.slice(0,3);const ok=stage===0?o==='float':stage===1?seen.float&&seen.sink:o==='float'&&volume()===mass()+1;if(ok){solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('afloat');}else state=stage===1?'compare':'wrong';render();if(solved&&stage<2)$('next').focus();}
function hints(){const g=target();return[t('Try changing just one thing. Watch what happens after each water test.','每次只改一樣東西。放進水中測試，看看有甚麼改變。'),t('Compare mass with volume: our water is 1 kg per litre. A sealed capsule floats at the surface when its total kg is smaller than its litres. Equal numbers stay submerged.','比較質量與體積：這裡的水每公升為 1 公斤。密封貨艙的公斤數小於公升數時會浮在水面；相等時停留在水中。'),stage===0?t(`Try ${g-1} kg in ${g} L.`,`試試 ${g} 公升、${g-1} 公斤。`):stage===1?t(`Keep ${g} kg. Test ${g-1} L, then ${g+1} L.`,`保持 ${g} 公斤。先測試 ${g-1} 公升，再測試 ${g+1} 公升。`):t(`Try ${g+1} L for ${g} kg.`,`試試用 ${g+1} 公升運載 ${g} 公斤。`)];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved),m=mass(),v=volume(),o=outcome();window.OrionDiscovery?.update(complete);document.title=t('The Sunken Harbour · Orion','沉沒港灣 · Orion');$('stageTitle').textContent=t(`Harbour seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道港口封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Harbour restored · ${count} / 3`,`已修復 ${count} / 3 道封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('instruction').textContent=t('Drag the slider or tap − / +. Then test the capsule in water.','拖動滑桿或點 − / +，再把貨艙放進水中測試。');$('adjustLabel').textContent=stage===0?t(`Total mass: ${m} kg`,`總質量：${m} 公斤`):t(`Outer volume: ${v} L`,`外部體積：${v} 公升`);$('adjustment').value=amount;$('adjustment').disabled=solved;$('minus').disabled=solved||amount===1;$('plus').disabled=solved||amount===10;$('minus').setAttribute('aria-label',t('Decrease by one','減少一格'));$('plus').setAttribute('aria-label',t('Increase by one','增加一格'));$('adjustment').setAttribute('aria-valuetext',stage===0?t(`${m} kilograms`,`${m} 公斤`):t(`${v} litres`,`${v} 公升`));$('settings').textContent=t(`Sealed capsule: ${m} kg total · ${v} L outer volume. Water: 1 kg/L. Gems are symbols.`,`密封貨艙：總質量 ${m} 公斤 · 外部體積 ${v} 公升。水：1 公斤／公升。晶石圖示只作象徵。`);
const width=65+v*19,y=!tested?25:o==='float'?95-50*(1-m/v):o==='neutral'?140:205;$('capsule').setAttribute('style',`transform:translateY(${y}px)`);$('shell').setAttribute('x',220-width/2);$('shell').setAttribute('width',width);$('glass').setAttribute('x',228-width/2);$('glass').setAttribute('width',width-16);$('cargo').textContent='◆'.repeat(Math.min(m,6));$('tank').setAttribute('aria-label',t(`Test basin. Capsule ${m} kg, ${v} L. `,`測試水池。貨艙 ${m} 公斤，${v} 公升。`)+(tested?label(o):t('Ready above the water.','在水面上方準備。')));
$('goal').textContent=goal();$('reading').textContent=tested?label(o)+t(` · ${m} ÷ ${v} = ${(m/v).toFixed(2)} kg/L`,` · ${m} ÷ ${v} = ${(m/v).toFixed(2)} 公斤／公升`):t('Ready on the quay. Test to see what happens.','已放在碼頭。測試看看結果。');$('evidence').hidden=stage!==1;$('evidence').textContent=t(`Same-mass evidence: ${seen.sink?'✓':'○'} sinking · ${seen.float?'✓':'○'} floating`,`相同質量的證據：${seen.sink?'✓':'○'} 下沉 · ${seen.float?'✓':'○'} 浮起`);
$('feedback').textContent={ready:t('The capsule is sealed. Follow the goal and try a water test.','貨艙已密封。跟着目標，試一次水中測試。'),changed:t('New design ready. Test it to record the result.','新設計準備好了。測試以記錄結果。'),compare:t('Keep the mass unchanged. Find the other result by changing only volume.','保持質量不變，只改體積，找出另一種結果。'),wrong:stage===2&&o==='float'?t('It floats! Can you use a smaller whole-litre capsule and still float?','浮起來了！能否用更小的整數公升貨艙，仍然浮起？'):o==='neutral'?t('It stays underwater. The goal needs the capsule to float at the surface.','它停留在水中。目標需要貨艙浮在水面。'):t('It sinks. Change the design and try again; nothing is lost.','下沉了。改一改設計再試，不會失去任何東西。'),success:stage===1?t('Same mass, different volumes, different results! A harbour seal opens.','相同質量，不同體積，結果不同！一道港口封印打開了。'):t('Cargo challenge solved! A harbour seal opens.','貨艙挑戰完成！一道港口封印打開了。')}[state];$('log').setAttribute('aria-label',t('Recent water tests','最近的水中測試'));$('log').innerHTML=history.map(h=>`<li>${h.m} kg / ${h.v} L · ${label(h.o)}</li>`).join('');
for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('afloat')?t('Afloat Sigil saved in your collection.','浮航符印已存入收藏。'):'';
}
$('adjustment').oninput=e=>adjust(Number(e.target.value));$('minus').onclick=()=>adjust(amount-1);$('plus').onclick=()=>adjust(amount+1);$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('adjustment').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('buoyancy',variant);observedVariant=OrionProgress.variant('buoyancy');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('afloat');render();};
function syncProgress(){const v=OrionProgress.variant('buoyancy'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('afloat')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
